message.content:
{
  "gate_token": "qeUE-PrwUll5i59Qn05aSQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map at the edge of the ruined city.",
guards    "visual_description": "A windswept overlook at dusk; broken spires and torn royal banners fill the valley below as Mara spreads a hand-drawn map across a stone.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of three traps ahead.",
      "visual_description": "Close shot of an old oil lamp held up in the dark; a single glowing eye blinks inside its flame, casting long shadows on Mara's face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with a key-wind tail creeps under the shadow of enormous iron gates hanging off their hinges, blue glass eyes glinting.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps out of a broken stained-glass window as if from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets in the abandoned plaza.",
      "visual_description": "A cracked fountain plaza at twilight; Mara, the Glass Diver, Tin Fox, and the Oracle Lamp gather around a faded royal seal carved into the flagstones.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened faces peek from boarded windows.",
      "visual_description": "Narrow alley lined with shuttered houses; Mara passes through while the Oracle Lamp throws warm light on planks nailed across windows.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of wings circle the cursed tower.",
      "visual_description": "A tall, leaning tower wrapped in green flame; vague serpentine shapes coil in the clouds above as Tin Fox watches from a rooftop.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Sleeping Tax Collector blocks a checkpoint.",
      "visual_description": "A wooden checkpoint booth where an official slumps face-down on a ledger, stamped papers stuck to his sleeves, while Mara tries to wave him aside.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox slips a key from the snoring official's belt.",
      "visual_description": "Close, comedic angle: the clockwork fox tip-toes across a desk, key dangling from its jaws, as the tax collector mumbles in his sleep.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrol marches past the alley mouth.",
      "visual_description": "From a low hiding place, plated boots and pike shafts pass in silhouette; Mara and the Glass Diver press flat against a mossy wall.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp reveals a hidden sigil.",
      "visual_description": "Lamp held close to a damp stone wall; its eye-flame projects a glowing rune over a doorway shaped like a closed mouth.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver dives through a tall mirror.",
      "visual_description": "An ornate cracked mirror ripples like water as the Glass Diver plunges in headfirst, coat tails trailing silver light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the magic door, prisoners wait in silence.",
      "visual_description": "A vaulted cell lit by floating candles; the Glass Diver steps out of a wall-mirror toward huddled figures whose faces are shown only in shadow.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara maps the escape route by lamplight.",
      "visual_description": "Mara crouches in a stairwell, brass compass spinning wildly, while the Oracle Lamp leans in over her shoulder, eye narrowed in thought.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox triggers a clattering distraction.",
      "visual_description": "The clockwork fox kicks over a stack of helmets in a barracks doorway, sparks flying from its tail as alarm bells begin to swing.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The team races down a banner-lined avenue.",
      "visual_description": "Tattered royal banners stream overhead as Mara, the Glass Diver, and Tin Fox sprint along wet cobblestones lit by torchfire.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the long stone bridge at dawn.",
      "visual_description": "A narrow arched bridge over a misty chasm; first light breaks behind the ruined skyline as the group steps onto the span, Oracle Lamp held high.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "Stones tumble into white fog behind the running figures; on the far bank Mara looks back, the Glass Diver shielding the Oracle Lamp while Tin Fox leaps the final gap.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

